<style lang="scss" src="./text-block.scss"></style>

<script>
import { Component, Vue } from "vue-property-decorator";
import MobileSwitch from "../mobile-switch/mobile-switch";
import { MobileSwitchSlot } from "../mobile-switch/mobile-switch.constants";

/**
 * This component is a page banner that displays chunks of text that divides up
 * evenly horizontally across the page. This will responsively stack the blurbs
 * of text atop each other for smaller mediums.
 *
 * Supports child p and b elements
 */
@Component({
  components: { MobileSwitch }
})
export default class TextBlock extends Vue {
  MobileSwitchSlot = MobileSwitchSlot;
}
</script>

<template>
  <div class="TextBlock">
    <div class="TextBlock__Content">
      <MobileSwitch>
        <template :slot="MobileSwitchSlot.MOBILE">
          <div class="TextBlock__Column">
            <slot />
          </div>
        </template>
        <template :slot="MobileSwitchSlot.DESKTOP">
          <div class="TextBlock__Row">
            <slot />
          </div>
        </template>
      </MobileSwitch>
    </div>
  </div>
</template>
